var e=[["Verifica las condiciones","Comprueba la continuidad en [a, b]. Si un extremo es ra\xEDz, termina; en otro caso exige f(a) \xB7 f(b) < 0."],["Calcula c","Une (a, f(a)) con (b, f(b)). Su cruce con el eje x es c = b \u2212 f(b)\xB7(b \u2212 a)/(f(b) \u2212 f(a))."],["Eval\xFAa la nueva aproximaci\xF3n","Calcula f(c). Si f(c) = 0, c es una ra\xEDz y el proceso termina."],["Comprueba la tolerancia","Desde la segunda iteraci\xF3n, compara |c\u2099 \u2212 c\u2099\u208B\u2081| con la tolerancia absoluta. Es un indicador a posteriori, no una garant\xEDa del error real."],["Conserva el intervalo izquierdo","Si f(a) y f(c) tienen signos opuestos, sustituye b por c y f(b) por f(c)."],["O conserva el intervalo derecho","En caso contrario, sustituye a por c y f(a) por f(c). Solo se conserva uno de los dos intervalos."],["Construye la siguiente cuerda","Repite desde el paso 2 con los extremos actualizados. Un extremo puede permanecer fijo; establece un m\xE1ximo de iteraciones."]];export{e as a};
